"""Normalize native-upload responses without retrying potentially accepted POSTs."""
from pathlib import Path
p=Path('/app/build/static/moara/feedback.js');s=p.read_text()
old="        const response = new Response(xhr.responseText, {status:xhr.status, statusText:xhr.statusText, headers:responseHeaders});\n        if (response.ok) {\n          try { const data = JSON.parse(xhr.responseText); if (data.id && url.searchParams.get('process') !== 'false') void poll(item, data.id, headers); else item.finish('Envio concluído — 100%', true); }\n          catch (_) { item.finish('Envio concluído. Confira o anexo no chat.'); }\n        } else item.finish('O servidor não aceitou o arquivo. Confira a mensagem do chat.');\n        resolve(response);"
new="        let data = null;\n        try { data = JSON.parse(xhr.responseText); } catch (_) { /* Proxy failures may have no JSON body. */ }\n        let statusCode = xhr.status >= 200 && xhr.status <= 599 ? xhr.status : 502;\n        const accepted = statusCode >= 200 && statusCode < 300;\n        if (!accepted || !data || typeof data !== 'object' || typeof data.id !== 'string' || !data.id) {\n          if (accepted) statusCode = 502;\n          const messages = {\n            401: 'Sua sessão expirou. Entre novamente para enviar o arquivo.',\n            403: 'Sua conta não tem permissão para enviar este arquivo.',\n            413: 'O arquivo excede o limite de 32 MB por envio. Divida o documento em arquivos menores.',\n            429: 'O servidor atingiu temporariamente o limite de envios. Aguarde um pouco e tente novamente.',\n            502: 'O servidor não confirmou o recebimento do arquivo. Confira seus anexos antes de tentar novamente.',\n            503: 'O serviço de arquivos está temporariamente indisponível. Tente novamente em instantes.',\n            504: 'O servidor demorou demais para confirmar o envio. Confira seus anexos antes de tentar novamente.'\n          };\n          const detail = messages[statusCode] || (typeof data?.detail === 'string' ? data.detail : 'Não foi possível enviar o arquivo (HTTP ' + statusCode + '). Tente novamente.');\n          item.finish(detail);\n          data = {detail};\n        } else if (url.searchParams.get('process') !== 'false') {\n          void poll(item, data.id, headers);\n        } else {\n          item.finish('Envio concluído — 100%', true);\n        }\n        responseHeaders.set('Content-Type', 'application/json; charset=utf-8');\n        responseHeaders.delete('Content-Length');\n        responseHeaders.delete('Content-Encoding');\n        resolve(new Response(JSON.stringify(data), {status:statusCode, headers:responseHeaders}));"
assert s.count(old)==1,'Upload integration point changed'
p.write_text(s.replace(old,new))
p=Path('/app/build/index.html');s=p.read_text()
assert 'feedback.js?v=20261027-documents' in s
p.write_text(s.replace('feedback.js?v=20261027-documents','feedback.js?v=20261027-upload-r5'))
print('Upload JSON validation and Portuguese proxy errors installed.')
